                    "sql": "create or replace table snitch_db.maplemonk.affiliate_new_com as with main_data as ( select order_timestamp::date as order_date, discount_code, order_name, tags, phone, email, new_customer_flag as customer_flag, case when webshopney = \'Web\' then \'Web\' else \'App\' end web_app_flag, sum(gross_sales_ex_coupon_discount) as sales, sum(coupon_discount) as discount, sum(dto_value) as dto_sales, sum(rto_value) as rto_sales, sum(ifnull(dto_sales,0) + ifnull(rto_sales,0)) AS returns, COALESCE(SUM(cancel_sales), 0) AS cancelled, state from snitch_db.maplemonk.fact_items_snitch where order_name in (select transactionid from snitch_db.maplemonk.affiliate_affiliate_web2_source_medium where lower(SESSIONSOURCEMEDIUM) like \'%affiliate%\') group by 1,2,3,4,5,6,7,8,15 ), orders_partner as ( select transactionid as ga4_order_name, upper(trim(split_part(sessionsourcemedium,\'/\',1))) as source_af_ga4, upper(trim(split_part(sessionsourcemedium,\'/\',1))) as partner_af_ga4, case when upper(trim(split_part(sessionsourcemedium,\'/\',2))) = \'AFFILIATE\' then upper(sessioncampaignname) else upper(trim(split_part(sessionsourcemedium,\'/\',2))) end as FINAL_UTM_MEDIUM_ga4, case when upper(trim(split_part(sessionsourcemedium,\'/\',2))) = \'AFFILIATE\' then upper(sessioncampaignname) else upper(trim(split_part(sessionsourcemedium,\'/\',1))) end as FINAL_UTM_SOURCE_ga4 from snitch_db.maplemonk.affiliate_affiliate_web2_source_medium qualify row_number() over (partition by transactionid order by _airbyte_emitted_at desc) = 1 and lower(SESSIONSOURCEMEDIUM) like \'%affiliate%\' ) select a.*, b.source_af_ga4 as source_af, b.partner_af_ga4 as partner_af, b.FINAL_UTM_MEDIUM_ga4 as final_utm_medium, b.FINAL_UTM_SOURCE_ga4 as final_utm_source, CASE WHEN lower(partner_af) = \'grabon\' and order_date < \'2025-12-17\' then 80 when lower(partner_af) = \'grabon\' and order_date >= \'2025-12-17\' and lower(customer_flag) = \'new\' then 0.08 * COALESCE(sales, 0)::float when low